     3	import hotel.reservations.Reservation;
     4	import hotel.rooms.Room;
     5	import java.math.BigDecimal;
     6	import java.math.RoundingMode;
     7	
     8	/** The invoice for a company, with the 5% ISS withheld. */
     9	final class CompanyInvoiceWriter implements DocumentWriter {
    10	
    11	    @Override
    12	    public String title() {
    13	        return "Fatura de hospedagem";
    14	    }
    15	
    16	    @Override
    17	    public String text(Reservation reservation, Room room) {
    18	        StringBuilder text = new StringBuilder();
    19	        text.append("Fatura de hospedagem nº ").append(reservation.id()).append('\n');
    20	        text.append("Empresa: ").append(reservation.guest().companyName())
    21	                .append(" (CNPJ ").append(reservation.guest().companyCnpj()).append(")\n");
    22	        text.append("Hóspede: ").append(reservation.guest().name()).append('\n');
    23	        text.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
    24	        int nights = reservation.price().nights();
    25	        text.append("Entrada: ").append(TextFormat.date(reservation.checkIn()))
    26	                .append(" | Saída: ").append(TextFormat.date(reservation.checkOut()))
    27	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    28	        text.append("Diárias: ").append(TextFormat.money(reservation.price().subtotal())).append('\n');
    29	        if (reservation.price().discount().signum() > 0) {
    30	            text.append("Desconto: ").append(TextFormat.money(reservation.price().discount())).append('\n');
    31	        }
    32	        text.append("Total: ").append(TextFormat.money(reservation.price().total())).append('\n');
    33	        BigDecimal withheldTax = reservation.price().total().multiply(new BigDecimal("0.05"))
    34	                .setScale(2, RoundingMode.HALF_EVEN);
    35	        text.append("ISS retido (5%): ").append(TextFormat.money(withheldTax)).append('\n');
    36	        return text.toString();
    37	    }
    38	}
